import raw from "./corpusAuthentic.json" with { type: "json" };
import type { ClaimCase, DecisionCase, ScreenCase } from "./corpusTypes.ts";

/** Generated by `buildAuthentic.ts` from retained commits, reports and records; not hand-edited. */
export const AUTHENTIC: ReadonlyArray<ScreenCase> = raw as unknown as ReadonlyArray<ScreenCase>;
export const claimCases = (cases: ReadonlyArray<ScreenCase>) =>
  cases.filter((c): c is ClaimCase => c.kind === "claim");
export const decisionCases = (cases: ReadonlyArray<ScreenCase>) =>
  cases.filter((c): c is DecisionCase => c.kind === "decision");
